class CrestApiFsSortOrderTest : public ::testing::Test {
 protected:
  std::string m_root;
  std::string m_tagname = "test_sort_order_tag";

  void SetUp() override {
    m_root =
        "/tmp/crest_sort_order_test_" +
        std::to_string(
            ::testing::UnitTest::GetInstance()->current_test_info()->line());
    std::filesystem::remove_all(m_root);
    std::filesystem::create_directories(m_root);
  }

  void TearDown() override { std::filesystem::remove_all(m_root); }

  ////////////////////////////////////////////////////////////////////////////////
  /// @brief  Create the test tag and store one IOV per (since, payload) pair,
  ///         in the exact order given.
  ////////////////////////////////////////////////////////////////////////////////
  void createTagWithIovs(
      CrestApiFs &api,
      const std::vector<std::pair<uint64_t, std::string> > &iovs) {
    TagDto tag;
    nlohmann::json js = {{"description", "sort-order test tag"},
                         {"endOfValidity", 0},
                         {"insertionTime", "2026-01-01T00:00:00.000+0000"},
                         {"lastValidatedTime", 0},
                         {"modificationTime", "2026-01-01T00:00:00.000+0000"},
                         {"name", m_tagname},
                         {"payloadSpec", "Json2Cool"},
                         {"synchronization", "ALL"},
                         {"timeType", "time"},
                         {"status", "UNLOCKED"}};
    tag = tag.fromJson(js);
    api.createTag(tag);

    for (const auto &iov : iovs) {
      StoreSetDto storeSetDto;
      StoreDto dto(iov.first, "", iov.second);
      storeSetDto.push_back(dto);
      api.storeData(m_tagname, storeSetDto, "JSON", "test", "test", "1", 0);
    }
  }

  static std::vector<uint64_t> sincesOf(IovSetDto &page) {
    std::vector<uint64_t> result;
    for (const IovDto &iov : page.getResources()) {
      result.push_back(iov.getSince());
    }
    return result;
  }
}

