TEST_F(CrestApiFsSortOrderTest, NanosecondSincesSortStrictlyAscending) {
  CrestApiFs api(true, m_root);
  constexpr uint64_t N = 1'700'000'000'000'000'000ULL;
  createTagWithIovs(api, {{N + 1, "alpha"}, {N, "beta"}, {N + 2, "delta"}});

  IovSetDto page = api.selectIovs(m_tagname, 0, static_cast<uint64_t>(-1), 0,
                                  1000, 0, "id.since:ASC");

  EXPECT_EQ(sincesOf(page), (std::vector<uint64_t>{N, N + 1, N + 2}));
}

TEST_F(CrestApiFsSortOrderTest, SameSecondOverrideResolvesToLaterRow) {
  CrestApiFs api(true, m_root);
  const std::string tagName = uniqueTagName("fs_override_order");
  TagDto tag(tagName, "time", "override order test tag");
  api.createTag(tag);

  constexpr int kPairs = 20;
  for (int i = 0; i < kPairs; ++i) {
    const uint64_t since = 1000 + i;
    for (const std::string which : {"first", "second"}) {
      StoreSetDto storeSet;
      storeSet.push_back(StoreDto(since, "", which + " " + std::to_string(i)));
      api.storeData(tagName, storeSet, "JSON", "test", "none", "1", 0);
    }
  }

  // iovs.json is in append order, so the last row per since is the override.
  std::ifstream in(m_root + "/tags/" + tagName + "/iovs.json");
  const nlohmann::json rows = nlohmann::json::parse(in);
  ASSERT_EQ(rows.size(), 2u * kPairs);
  std::map<uint64_t, std::string> expectedHash;
  int sameSecondPairs = 0;
  for (std::size_t r = 0; r < rows.size(); r += 2) {
    ASSERT_EQ(rows[r]["since"], rows[r + 1]["since"]);
    ASSERT_NE(rows[r]["payloadHash"], rows[r + 1]["payloadHash"]);
    expectedHash[rows[r + 1]["since"].get<uint64_t>()] =
        rows[r + 1]["payloadHash"];
    if (rows[r]["insertionTime"] == rows[r + 1]["insertionTime"]) {
      ++sameSecondPairs;
    }
  }
  // Only same-second pairs exercise the tie; a pair straddling a second
  // boundary is ordered by insertionTime alone.
  ASSERT_GE(sameSecondPairs, kPairs / 2);

  IovSetDto page = api.selectIovs(tagName, 0, static_cast<uint64_t>(-1), 0,
                                  1000, 0, "id.since:ASC");
  const std::vector<IovDto> &iovs = page.getResources();
  ASSERT_EQ(iovs.size(), 2u * kPairs);
  for (std::size_t r = 0; r < iovs.size(); r += 2) {
    EXPECT_EQ(iovs[r].getSince(), iovs[r + 1].getSince());
    EXPECT_EQ(iovs[r].getPayloadHash(), expectedHash[iovs[r].getSince()])
        << "since " << iovs[r].getSince();
  }
}

TEST_F(CrestApiFsSortOrderTest, NewerInsertionTimeWinsOverPosition) {
  CrestApiFs api(true, m_root);
  const std::string tagName = uniqueTagName("fs_override_order");
  TagDto tag(tagName, "time", "override order test tag");
  api.createTag(tag);

  const nlohmann::json rows =
      nlohmann::json::array({{{"tagName", tagName},
                              {"since", 5},
                              {"insertionTime", "2026-01-01 00:00:02"},
                              {"payloadHash", "newer"}},
                             {{"tagName", tagName},
                              {"since", 5},
                              {"insertionTime", "2026-01-01 00:00:01"},
                              {"payloadHash", "older"}}});
  std::ofstream(m_root + "/tags/" + tagName + "/iovs.json") << rows.dump();

  IovSetDto page = api.selectIovs(tagName, 0, static_cast<uint64_t>(-1), 0,
                                  1000, 0, "id.since:ASC");
  ASSERT_EQ(page.size(), 2u);
  EXPECT_EQ(page.getResources()[0].getPayloadHash(), "newer");
}
